export function requirementsFor(lead = {}) {
  return { goal: 'Help visitors understand the services and make an enquiry', audience: 'Local customers looking for these services', services: lead.services?.length ? [...lead.services] : ['Consultations'], style: 'clean', theme: 'light', layout: 'centered', accent: '#245fa3', sections: ['about', 'services', 'faq', 'enquiry'], features: [], notes: 'Keep the page clear and specific.' };
}
export function designFor(brief) {
  return { headline: ['Your requirements.', 'A website shaped around them.'], intro: `A concept for ${brief.audience}.`, aboutTitle: 'A closer look at the business', description: `This concept focuses on ${brief.goal.toLowerCase()}.`, serviceTitle: 'Explore the approved services', workTitle: 'Illustrative directions', contactTitle: 'Tell us what you need', primaryCta: 'Ask about a service', services: brief.services.map(title => ({ title, description: `Explore ${title} and ask about the details of your enquiry.` })), process: [{ title: 'Discuss', text: 'Share what you need.' }, { title: 'Clarify', text: 'Consider the available options.' }, { title: 'Plan', text: 'Confirm a useful next step.' }], faqs: [{ question: 'What can I ask about?', answer: brief.services.join(', ') }, { question: 'How do I start?', answer: 'Use the sample enquiry to describe your requirements.' }, { question: 'Does this form send a message?', answer: 'This is a demo. No customer request is sent.' }], projectNames: ['An introduction concept', 'A service journey concept', 'An enquiry concept'] };
}
